using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using Newtonsoft.Json;
using WF=System.Windows.Forms;
namespace PhotoTutor {
 internal static class FormulaBoundaryChecks {
  const string Formula=@"|PF_1|\cdot |PF_2|\le \left(\frac{|PF_1|+|PF_2|}{2}\right)^2=2^2=4.";
  internal const string Example="$$\\lambda=-\\frac{1}{7}.$$\n$\\triangle PBF_1$ 的周长 $=|PB|+|PF_1|+|BF_1|$。\n由均值不等式，\n$$\n"+Formula+" $$\n当 $|PF_1|=|PF_2|$ 时取等号，即 $P$ 为短轴端点 $(0,\\pm1)$ 时。因此\n（2）设 $C(x,y)$，因为 $C$ 在椭圆上，代入椭圆方程。\n$$\n=6+\\bigl(|PB|-|PF_2|\\bigr). $$\n后续正文应正常显示。";
  static IEnumerable<WF.Control> All(WF.Control root){foreach(WF.Control child in root.Controls){yield return child;foreach(var c in All(child))yield return c;}}
  internal static int Run(string folder){Directory.CreateDirectory(folder);Settings.IsolatedTestRoot=Path.Combine(folder,"isolated-runtime");int failed=0,calls=0;var checks=new List<object>();void Check(string name,Action test){try{test();checks.Add(new{name,passed=true});}catch(Exception e){failed++;checks.Add(new{name,passed=false,error=e.ToString()});}}
   ScienceSupport.CloudMath.TestRenderer=(f,s)=>{calls++;return Task.FromException<byte[]>(new IOException("offline: unavailable layout retains source"));};
   try {
    Check("screenshot delimiter layout keeps following prose outside formulas",()=>{using(var panel=new LessonPanel{Width=1500,Height=1000}){panel.Display(Example,true);if(All(panel).OfType<WF.Label>().Any(x=>x.ForeColor==Color.DarkRed))throw new Exception("standard screenshot formulas entered error fallback");if(!panel.Controls.Cast<WF.Control>().Any(c=>(c.Text+" "+c.AccessibleName).Contains("后续正文应正常显示")))throw new Exception("following prose was swallowed");}});
    foreach(string formula in new[]{Formula,@"=6+\bigl(|PB|-|PF_2|\bigr).",@"\Bigl\{\frac{1}{2}\Bigr\}",@"\lambda=-\frac{1}{7}",@"\triangle PBF_1=|PB|+|PF_1|+|BF_1|"})Check("local renderer / "+formula,()=>{using(var bitmap=FormulaRaster.Local(formula,32)){if(bitmap.Width<2||bitmap.Height<2)throw new Exception("empty formula");}});
    Check("same-line display formula with prose on both sides",()=>{using(var panel=new LessonPanel{Width=1500}){panel.Display("先看结论 $$x=1$$ 然后 $y=2$。",true);if(All(panel).OfType<WF.Label>().Any(x=>x.Text.Contains("$$")))throw new Exception("display delimiter leaked");}});
    Check("closing display delimiter followed by prose on same line",()=>{using(var panel=new LessonPanel{Width=1500}){panel.Display("$$\nx=1$$ 因此结论成立。\n下一步。",true);if(All(panel).OfType<WF.Label>().Any(x=>x.ForeColor==Color.DarkRed||x.Text.Contains("$$")))throw new Exception("closing delimiter not parsed");}});
    Check("failed formula is confined to its own source",()=>{using(var panel=new LessonPanel{Width=1500}){panel.Display("$$\n\\unsupportedForTest{x}$$\n后面的普通正文 $x=1$ 保留。",true);var errors=All(panel).OfType<WF.Label>().Where(x=>x.ForeColor==Color.DarkRed).ToArray();if(errors.Length!=1||!errors[0].Text.Contains(@"\unsupportedForTest{x}")||errors[0].Text.Contains("后面的普通正文"))throw new Exception("fallback consumed prose or lost source");}});
    Check("unclosed display math does not consume later paragraph",()=>{using(var panel=new LessonPanel{Width=1500}){panel.Display("$$x=1\n\n这里开始普通正文，$y=2$。\n后续正文。",true);if(!panel.Controls.Cast<WF.Control>().Any(c=>(c.Text+" "+c.AccessibleName).Contains("这里开始普通正文")))throw new Exception("unclosed formula consumed prose");}});
    Check("streaming remains one lightweight control",()=>{using(var panel=new LessonPanel{Width=1200}){for(int i=1;i<=20;i++){panel.Display(Example.Substring(0,Example.Length*i/20),true,false,true);if(panel.Controls.Count!=1)throw new Exception("streaming now formats on each token");}}});
    foreach(string text in new[]{"$$x=1$$", "$$\nx=1$$", "$$x=1\n$$", "$$\nx=1\n$$", @"\[x=1\]", "\\[\nx=1\\]"})Check("display delimiter positions / "+text,()=>{var parts=MathDocument.Parse(text);if(parts.Count!=1||parts[0].Kind!=MathKind.Block||parts[0].Content.Trim()!="x=1")throw new Exception("display content or boundaries changed");});
    Check("multiple formula spans preserve text and equation order",()=>{var parts=MathDocument.Parse(@"甲$$x=1$$乙\(y=2\)丙$z=3$丁\[t=4\]戊");if(string.Concat(parts.Select(p=>p.Source))!=@"甲$$x=1$$乙\(y=2\)丙$z=3$丁\[t=4\]戊"||string.Join(",",parts.Where(p=>p.Kind!=MathKind.Text).Select(p=>p.Content))!="x=1,y=2,z=3,t=4")throw new Exception("equations reordered or source changed");});
    Check("escaped currency is text and does not absorb real equations",()=>{var parts=MathDocument.Parse(@"价格\$5，公式 $x=1$，另付\$2。");if(parts.Count(p=>p.Kind==MathKind.Inline)!=1||parts.Single(p=>p.Kind==MathKind.Inline).Content!="x=1"||!parts[0].Content.Contains("$5"))throw new Exception("escaped dollar parsed as formula");});
    Check("Chinese explicit text inside formula is retained for existing fallback",()=>{string value="\\[x=1+\\text{\n已知条件}\n\\]";var parts=MathDocument.Parse(value);if(parts.Count!=1||parts[0].Kind!=MathKind.Block||!parts[0].Content.Contains("已知条件"))throw new Exception("text group incorrectly treated as prose");});
    Check("unclosed formula before prose without blank line recovers",()=>{var parts=MathDocument.Parse("$$\nx=1\n因此 $y=2$。\n正常正文");if(parts[0].Kind!=MathKind.Invalid||parts[0].Content.Contains("因此")||!parts.Any(p=>p.Kind==MathKind.Inline&&p.Content=="y=2"))throw new Exception("prose absorbed into unclosed formula");});
    Check("invalid inline does not borrow half a following display delimiter",()=>{var parts=MathDocument.Parse("未闭合 $x\n$$y=2$$\n结束");if(parts.Count(p=>p.Kind==MathKind.Block)!=1||parts.Single(p=>p.Kind==MathKind.Block).Content!="y=2")throw new Exception("mixed delimiter recovery failed");});
    foreach(string size in new[]{"big","Big","bigg","Bigg"})Check("fixed delimiter family preserves symbols / "+size,()=>{string value="\\"+size+"l(|x_1|-|x_2|)\\"+size+"r";if(ScienceSupport.ScientificNotation.Normalize(value)!="(|x_1|-|x_2|)")throw new Exception("delimiter or symbol changed");using(var image=FormulaRaster.Local("\\"+size+"l(|x_1|-|x_2|\\"+size+"r)",32))if(image.Width<2)throw new Exception("empty layout");});
    Check("size normalization leaves unrelated commands and original source intact",()=>{if(ScienceSupport.ScientificNotation.Normalize(@"\bigstar+x_1^2")!=@"\bigstar+x_1^2")throw new Exception("unrelated command removed");using(var panel=new LessonPanel{Width=1200}){string bad=@"\bigl(\unsupportedForTest{x}\bigr)";panel.Display("$$"+bad+"$$\n原文保留",true);if(!All(panel).OfType<WF.Label>().Any(x=>x.ForeColor==Color.DarkRed&&x.Text.Contains(bad)))throw new Exception("fallback lost original size commands");}});
    Check("plain display mode preserves original delimiters",()=>{using(var panel=new LessonPanel{Width=1200}){panel.Display("原文 $$x=1$$",false);if(!All(panel).OfType<WF.Label>().Any(x=>x.Text.Contains("$$x=1$$")))throw new Exception("plain mode altered source");}});
    Check("parenthesized numbers at start of math are not prose headings",()=>{foreach(string formula in new[]{"(1)^2+(2)^2=5","(12)+3=15","(1)"}){var parts=MathDocument.Parse("$$\n"+formula+"\n$$");if(parts.Count!=1||parts[0].Kind!=MathKind.Block||parts[0].Content.Trim()!=formula)throw new Exception("valid numbered expression treated as prose: "+formula);using(var panel=new LessonPanel{Width=1200}){panel.Display("$$\n"+formula+"\n$$",true);if(All(panel).OfType<WF.Label>().Any(x=>x.ForeColor==Color.DarkRed))throw new Exception("valid numeric expression failed");}}});
    Check("numbered Chinese prose remains outside an unclosed formula",()=>{var parts=MathDocument.Parse("$$x=1\n（2）设 $C(x,y)$，后续正文");if(parts[0].Kind!=MathKind.Invalid||parts[0].Content.Contains("设")||!parts.Any(p=>p.Kind==MathKind.Inline&&p.Content=="C(x,y)"))throw new Exception("numbered prose consumed");});
    foreach(int width in new[]{380,1500})Check("screenshot formulas render offline at classroom widths / "+width,()=>{int before=calls;using(var panel=new LessonPanel{Width=width,Height=1000}){panel.Display(Example,true);if(calls!=before||All(panel).OfType<WF.Label>().Any(x=>x.ForeColor==Color.DarkRed||x.Text.Contains(@"\bigl")||x.Text.Contains("$$")))throw new Exception("valid standard formulas need network or leak raw commands");}});
    using(var form=new WF.Form{Width=1560,Height=1050,ShowInTaskbar=false,StartPosition=WF.FormStartPosition.Manual,Location=new Point(-12000,-12000)})using(var panel=new LessonPanel{Dock=WF.DockStyle.Fill}){form.Controls.Add(panel);form.Show();panel.Display(Example,true);WF.Application.DoEvents();using(var bitmap=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bitmap,new Rectangle(Point.Empty,form.Size));bitmap.Save(Path.Combine(folder,"截图公式_实际讲解控件.png"));}form.Close();}
   }finally{ScienceSupport.CloudMath.TestRenderer=null;}
   File.WriteAllText(Path.Combine(folder,"公式定界与符号回归.json"),JsonConvert.SerializeObject(new{failed,checks,cloudSubstituteCalls=calls,paidCalls=0,realSchoolHardware=false},Formatting.Indented));return failed==0?0:1;
  }
 }
}
